const connections = new Map(); // userId -> WebSocket object

function onConnect(userId, ws) {
  connections.set(userId, ws); // actual socket handle stays in this process
}

function sendToLocalUser(userId, msg) {
  const ws = connections.get(userId);
  if (ws) ws.send(JSON.stringify(msg));
}

